-- C3-3 follow-up: refresh token reuse detection. `rotated` marks a row spent
-- by a refresh, as distinct from one revoked by a sign-out, a password change
-- or an account change, so a rotated token presented again can be told from a
-- stale one (CncTokenService.redeemRefreshToken).
--
-- Generated by `prisma migrate dev --create-only`. Existing rows take false:
-- a token rotated before this column existed is not recognised as replayed,
-- which is the behaviour before the change, never a false alarm.

-- AlterTable
ALTER TABLE "RefreshToken" ADD COLUMN     "rotated" BOOLEAN NOT NULL DEFAULT false;
